    sort: bool = True,
) -> None:
    if is_nautilus_class(result.data_cls):
        engine.add_data(
            data=result.data,
            sort=sort,
        )
    else:
        if not result.client_id:
            raise ValueError(
                f"Data type {result.data_cls} not setup for loading into `BacktestEngine`",
            )

        engine.add_data(
            data=result.data,
            client_id=result.client_id,
            sort=sort,
        )

